import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { loginHandler } from "../handlers/loginHandler";
import type { ApiError } from "../runtime/client";
import type { LoginRequest } from "../types/LoginRequest";

type Data = Awaited<ReturnType<typeof loginHandler>>;
type Vars = LoginRequest;

export function useLogin(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => loginHandler(vars),
    ...options,
  });
}
